def transform(grid):
    g=[row[:] for row in grid]
    cells=[(r,c) for r,row in enumerate(g) for c,v in enumerate(row) if v]
    if not cells: return g
    r0=min(r for r,c in cells); r1=max(r for r,c in cells)
    c0=min(c for r,c in cells); c1=max(c for r,c in cells)
    # The inner color is the less frequent of the two non-background colors.
    counts={v:sum(row.count(v) for row in g) for v in {g[r][c] for r,c in cells}}
    inner=min(counts,key=counts.get)
    # Paint the two-cell surrounding rectangular margin, preserving all object cells.
    for r in range(max(0,r0-2),min(len(g),r1+3)):
        for c in range(max(0,c0-2),min(len(g[0]),c1+3)):
            if g[r][c]==0:
                g[r][c]=inner
    return g

